export function normalizeElevator(raw={}){const r=raw&&typeof raw==='object'?raw:{};const progress=elevatorDecks.map((d,i)=>Number.isInteger(r.progress?.[i])?Math.max(0,Math.min(d.steps,r.progress[i])):0);const rescued=elevatorDecks.map((d,i)=>r.rescued?.[i]===true&&progress[i]===d.steps);let reached=rescued.indexOf(false);if(reached<0)reached=6;const deck=Number.isInteger(r.deck)?Math.max(0,Math.min(reached,r.deck,6)):0;const boss=reached===6&&Number.isInteger(r.boss)?Math.max(0,Math.min(4,r.boss)):0;return {started:r.started===true,deck,progress,rescued,boss,resolved:boss===4};}
