export const elevatorOrders=[['release'],['support','lift'],['compare','gain','calibrate'],['trace','isolate'],['toward'],['scan','balance']];
export const elevatorStages=[['gate','gate-open'],['cargo','cargo-support','cargo-clear'],['crystal','crystal-compare','crystal-gain','crystal-ready'],['network','network-traced','network-clear'],['drones','drones-aligned'],['air','air-scanned','air-balanced']];
export function elevatorObjective(s){if(s.deck===6)return s.resolved?'Everyone is safe. Follow the crystal signal to the Moon.':['Observe the hammer pulse pattern.','Brace the deck with the team.','Use the cargo barrier to interrupt the hammer.','Tap a cartoon bolt to disarm the crystal hammer.'][s.boss];const d=elevatorDecks[s.deck];return s.rescued[s.deck]?'Crew safe. Choose Next deck.':s.progress[s.deck]===d.steps?'System restored. Free the people in the rescue area.':'Next: '+d.actions.find(([,id])=>id===elevatorOrders[s.deck][s.progress[s.deck]])[0]+'. Then rescue the crew.';}
export function elevatorView(raw,page='intro'){const s=normalizeElevator(raw),d=elevatorDecks[Math.min(s.deck,5)];let title='Adventure 1: The Space Elevator Hack',text='',art='opening',actions=[];const add=(label,id)=>actions.push([label,id]);
 if(page==='intro'){text='The year is 2063. The J.A.C.C. Space Elevator carries astronauts and scientists toward the stars. Today, the ride has a glitch… Starring Alex, Malik, Aiden, Kaito and Maya; Lucas supports the upper-deck rescue.';add(s.started?'▶ Continue elevator rescue':'▶ Start elevator rescue','start');add('🎬 Nymlord’s message','page:threat');add('🧑‍🚀 Choose astronaut','crew');if(s.started)add('↻ Replay elevator','page:restart');}
 else if(page==='threat'){title='Nymlord takes the screen';text='Steady purple lights mark the hack. A tall armored warrior appears; mantis-like eyes glint beneath his helmet. NYMLORD: “People of Earth! Your elevator now answers to the Nymions!” PIP: “Definitely not the usual welcome message. People are trapped!”';art='nymlord';add('▶ Start / continue rescue','start');add('← Chapter opening','page:intro');}
 else if(page==='restart'){title='Replay the elevator?';text='Reset this rescue and try it again? Home collections, crew, PIP, construction and Moon progress stay saved.';add('↻ Restart elevator rescue','restart');add('← Keep my rescue','page:intro');}
 else if(page==='tick-ship'){title='Nymlord’s tick ship trail';text='The hammer crystal signal points to the Nymion tick ship on the Moon. Nymlord and Zuglu escaped here. PIP marks the trail while the team explores the mines.';art='escape';add('📖 Adventure chapters','chapters');}
 else if(s.deck===6){title=s.resolved?'The elevator is safe':'Commander Zuglu';art=['zuglu','pulse','brace','interrupt','escape'][s.boss];text=s.resolved?'A final shockwave rattles the deck. NYMLORD: “Zuglu! The tick ship! We leave now!” They escape. Everyone is safe, the elevator is back on course, and the hammer crystal signal points to the Moon. PIP: “Next stop: the Moon!”':'Zuglu stomps in with a crystal-tipped hammer! Ordinary Zugu are small, docile, squid-faced underground creatures that eat fungi. This mutated, armored commander is different. PIP: “That hammer’s sound wave is rattling the floor and scrambling computers!”';
 if(page==='inspect')text='The crystal-tipped hammer emits a repeating pulse. Our stylized visible rings represent vibrations; sound itself is usually invisible. In this story the vibration disrupts the electronics. Watch or listen again whenever you like.';
 if(page==='hint')text=elevatorObjective(s)+' PIP: “The model waits for you. We can work together, one step at a time.”';
 if(!s.resolved){const labels=['◉ Observe pulse pattern','▰ Brace the deck','🏗 Raise cargo barrier','⚡ Disarm hammer / cartoon bolt'];add(labels[s.boss],'boss:'+s.boss);if(page!=='hint')add('🤖 PIP hint','page:hint');}
 else {add('🌙 Follow the tick ship','moon');add('↻ Replay finale','page:finale');}
 }
 else {title=(s.deck+1)+'/6 • '+d.name;text=d.lead+'. '+elevatorObjective(s);art=elevatorStages[s.deck][s.progress[s.deck]];
 if(page==='inspect'){text=d.inspect;add('⚙ Try the system','page:system');}
 else if(page==='hint'){text='PIP: “'+elevatorObjective(s)+' You can explore or come back whenever you like.”';add('⚙ System station','page:system');}
 else if(page==='rescue'){art=s.rescued[s.deck]?'rescue-safe':'rescue-wait';text=s.rescued[s.deck]?d.rescue:s.progress[s.deck]===d.steps?'The system is ready. Open the rescue doors when you are ready.':'The rescue doors wait safely while we restore this deck’s system.';if(!s.rescued[s.deck]&&s.progress[s.deck]===d.steps)add('🧑‍🚀 Free the people','rescue');else add('⚙ System station','page:system');}
 else if(page==='next'){text=s.rescued[s.deck]?'The team is ready for the next deck. Explore here again, or continue.':'Finish this deck’s system and rescue before going up.';if(s.rescued[s.deck])add(s.deck===5?'⬆️ Upper platform':'⬆️ Next deck','next');else add('🤖 PIP hint','page:hint');}
 else {text=s.progress[s.deck]===d.steps?d.success:d.inspect+' Step '+(s.progress[s.deck]+1)+' of '+d.steps+'.';if(s.progress[s.deck]<d.steps)for(const [label,id]of d.actions)add((id===elevatorOrders[s.deck][s.progress[s.deck]]?'▶ ':'')+label,'science:'+id);else add('🧑‍🚀 Rescue area','page:rescue');}
 if(page!=='hint'&&!actions.some(([,id])=>id==='page:hint')&&actions.length<4)add('🤖 PIP hint','page:hint');}
 return {title,text,art,actions};}
export function elevatorAction(raw,action){let s=normalizeElevator(raw),route='system',travel=null,message='';
 if(action==='start'){s.started=true;travel='elevator';}
 else if(action==='restart'){s=normalizeElevator({started:true});travel='elevator';}
 else if(action==='crew')travel='crew';else if(action==='chapters')travel='chapters';else if(action==='moon'&&s.resolved)travel='moon';
 else if(action.startsWith('page:'))route=action.slice(5);
 else if(action==='rescue'&&s.deck<6&&s.progress[s.deck]===elevatorDecks[s.deck].steps){s.rescued[s.deck]=true;route='rescue';}
 else if(action==='next'&&s.deck<6&&s.rescued[s.deck]){s.deck++;travel='elevator';}
 else if(action.startsWith('science:')&&s.deck<6&&!s.rescued[s.deck]){const id=action.slice(8),order=elevatorOrders[s.deck];if(id===order[s.progress[s.deck]])s.progress[s.deck]++;else message='PIP: “Let’s observe and try the next step. Nothing is lost.”';}
 else if(action==='boss:'+s.boss&&s.deck===6&&s.boss<4){s.boss++;s.resolved=s.boss===4;route=s.resolved?'finale':'system';}
 return {elevator:s,route,travel,message};}
